referenceSolutions.javascript:
export function twoSum(values, target) {
  const seen = new Map();
  for (let i = 0; i < values.length; i++) {
    const previous = seen.get(target - values[i]);
    if (previous !== undefined) return [previous, i];
    seen.set(values[i], i);
  }
  return [];
}

referenceSolutions.typescript:
export function twoSum(values: number[], target: number): number[] {
  const seen = new Map<number, number>();
  for (let i = 0; i < values.length; i++) {
    const previous = seen.get(target - values[i]);
    if (previous !== undefined) return [previous, i];
    seen.set(values[i], i);
  }
  return [];
}
